<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,nextTick} from 'vue'
import axios from 'axios'
import {sha256} from '@noble/hashes/sha2.js'
import {nodeMediaUrl} from '../utils/adPlacement'
const base='/api/v1/admin/ads'
const headers=()=>({Authorization:'Bearer '+(localStorage.getItem('admin_token')||'cookie-session')})
const mode=ref('campaigns'),busy=ref(false),error=ref(''),notice=ref('')
const creatives=ref<any[]>([]),rules=ref<any[]>([]),videos=ref<any[]>([]),total=ref(0),offset=ref(0),q=ref(''),kind=ref('movie')
const title=ref(''),file=ref<File|null>(null),fileInput=ref<HTMLInputElement|null>(null),cta=ref(''),skip=ref<number|null>(null),progress=ref(0)
const selected=ref<any>(null),cues=ref<any[]>([]),revision=ref(0),source=ref('none'),creativeId=ref(''),dirty=ref(false)
const main=ref<HTMLVideoElement|null>(null),mainUrl=ref(''),duration=ref(0),position=ref(0),previewId=ref(''),previewUrl=ref(''),editing=ref('')
const testAd=ref(''),testCue=ref<any>(null),testReturn=ref(0),testBlocked=ref(false),adVideo=ref<HTMLVideoElement|null>(null)
const globalEnabled=ref(false),globalPre=ref(true),globalMid=ref(false),globalPost=ref(false),minutes=ref(25),globalCreative=ref('')
let session='',heartbeat:ReturnType<typeof setInterval>|null=null,disposed=false
const uuid=()=>crypto.randomUUID?.()||'10000000-1000-4000-8000-100000000000'.replace(/[018]/g,c=>(Number(c)^crypto.getRandomValues(new Uint8Array(1))[0]&15>>Number(c)/4).toString(16))
const ordered=computed(()=>[...cues.value].sort((a,b)=>cueSecond(a)-cueSecond(b)))
const globalRule=computed(()=>rules.value.find(r=>r.scope==='all'&&r.genre_id==null))
function format(s:number){return [Math.floor((s||0)/3600),Math.floor((s||0)%3600/60),Math.floor((s||0)%60)].map(x=>String(x).padStart(2,'0')).join(':')}
function rate(n:number,d:number){return d?(100*n/d).toFixed(1)+'%':'—'}
function cueSecond(c:any){return c.kind==='pre'?0:c.kind==='post'?duration.value:c.at_sec}
function cueLabel(c:any){return c.kind==='pre'?'Pre-roll · начало':c.kind==='post'?'Post-roll · конец':'Mid-roll · '+format(c.at_sec)}
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e:any){error.value=typeof e.response?.data?.detail==='string'?e.response.data.detail:e.message||'Операция не выполнена'}finally{busy.value=false}}
async function load(){const [c,r]=await Promise.all([axios.get(base+'/creatives',{headers:headers()}),axios.get(base+'/rules',{headers:headers()})]);creatives.value=c.data;rules.value=r.data;const g=globalRule.value;globalEnabled.value=g?.enabled??false;globalPre.value=g?.preroll??true;globalPost.value=g?.postroll??false;globalMid.value=!!g?.interval_sec;minutes.value=g?.interval_sec?g.interval_sec/60:25;globalCreative.value=g?.creative_id||''}
async function catalog(){const r=await axios.get(base+'/videos',{params:{kind:kind.value,q:q.value,offset:offset.value,limit:30},headers:headers()});videos.value=r.data.items;total.value=r.data.total}
function search(){offset.value=0;void action(catalog)}
function page(n:number){offset.value+=n;void action(catalog)}
function selectFile(e:Event){file.value=(e.target as HTMLInputElement).files?.[0]||null;if(file.value&&!title.value)title.value=file.value.name.replace(/\.[^.]+$/,'').slice(0,160)}
function upload(){void action(async()=>{const f=file.value;if(!f||!title.value.trim())throw Error('Выберите файл и название');if(f.size>104857600)throw Error('Максимальный размер — 100 МиБ');progress.value=0;await axios.get('/api/v1/auth/me',{timeout:10000});const hash=Array.from(sha256(new Uint8Array(await f.arrayBuffer())),x=>x.toString(16).padStart(2,'0')).join('');const mime=f.type||(/\.webm$/i.test(f.name)?'video/webm':'video/mp4');const t=(await axios.post(base+'/creatives/upload-ticket',{title:title.value.trim(),cta_url:cta.value,cta_text:cta.value?'Подробнее':'',skip_after:skip.value,status:'active',size:f.size,mime,sha256:hash},{headers:headers()})).data;const url=nodeMediaUrl(t.upload_url);const result=await axios.put(url,f,{headers:{Authorization:'Bearer '+t.upload_token,'Content-Type':mime},withCredentials:false,timeout:240000,onUploadProgress:e=>{progress.value=Math.round(100*e.loaded/(e.total||f.size))}});await axios.post(base+'/creatives/upload-complete',{receipt:result.data.receipt},{headers:headers()});file.value=null;title.value='';cta.value='';if(fileInput.value)fileInput.value.value='';await load();notice.value='Ролик активен. Видео загружено напрямую на Media Node.'})}
function saveCreative(c:any){void action(async()=>{await axios.put(base+'/creatives/'+c.id,{title:c.title,cta_url:c.cta_url,cta_text:c.cta_text,skip_after:c.skip_after,status:c.status},{headers:headers()});await load();notice.value='Настройки ролика сохранены'})}
function toggle(c:any){saveCreative({...c,status:c.status==='active'?'paused':'active'})}
function showPreview(c:any){void action(async()=>{previewId.value=c.id;previewUrl.value=nodeMediaUrl((await axios.get(base+'/creatives/'+c.id+'/preview',{headers:headers()})).data.media_url)})}
function saveGlobal(){void action(async()=>{if(globalEnabled.value&&!globalPre.value&&!globalMid.value&&!globalPost.value)throw Error('Выберите место показа');await axios.put(base+'/rules/'+(globalRule.value?.id||uuid()),{scope:'all',genre_id:null,enabled:globalEnabled.value,preroll:globalPre.value,postroll:globalPost.value,interval_sec:globalMid.value?minutes.value*60:0,creative_id:globalCreative.value||null},{headers:headers()});await load();await catalog();notice.value='Авто-правило сохранено. Индивидуальные настройки видео имеют приоритет.'})}
async function stopPreview(){if(heartbeat)clearInterval(heartbeat);heartbeat=null;main.value?.pause();adVideo.value?.pause();testAd.value='';testCue.value=null;mainUrl.value='';const id=session;session='';if(id)try{await axios.post('/api/v1/playback/stop',{session_id:id},{headers:headers(),timeout:5000})}catch{/* Lease expires safely. */}}
async function startPreview(){if(!selected.value)return;const movie=selected.value.kind==='movie';const r=(await axios.post(movie?'/api/v1/playback/start':'/api/v1/series_playback/start',movie?{movie_id:selected.value.id}:{episode_id:selected.value.id},{headers:headers()})).data;const url=nodeMediaUrl(r.media_url);session=r.session_id||'';if(disposed){await stopPreview();return}mainUrl.value=url;if(session)heartbeat=setInterval(()=>{if(session)void axios.post('/api/v1/playback/heartbeat',{session_id:session},{headers:headers(),timeout:5000}).catch(()=>{})},Math.max(5,r.heartbeat_interval_seconds||15)*1000)}
function openVideo(v:any){if(dirty.value&&!confirm('Несохранённые точки будут потеряны. Продолжить?'))return;void action(async()=>{await stopPreview();selected.value=v;mode.value='timeline';position.value=0;duration.value=v.duration_sec||0;const data=(await axios.get(base+'/videos/'+v.kind+'/'+v.id,{headers:headers()})).data;cues.value=data.cues;revision.value=data.revision;source.value=data.source;dirty.value=false;await startPreview()})}
function add(kind:string,second=0){if(kind==='mid'&&(!duration.value||second<=0||second>=duration.value)){error.value='Выберите момент внутри видео';return}second=kind==='mid'?Math.round(second):0;if(cues.value.some(c=>c.kind===kind&&c.at_sec===second)){error.value='Такая точка уже есть';return}cues.value.push({id:uuid(),kind,at_sec:second,creative_id:creativeId.value||null});dirty.value=true}
function seek(e:Event){const s=Number((e.target as HTMLInputElement).value);position.value=s;if(main.value)main.value.currentTime=s}
function move(c:any,s:number){if(c.kind!=='mid')return;const next=Math.max(1,Math.min(Math.round(duration.value)-1,Math.round(s)));if(cues.value.some(x=>x.id!==c.id&&x.kind==='mid'&&x.at_sec===next))return;c.at_sec=next;dirty.value=true}
function drag(c:any,e:PointerEvent){if(c.kind!=='mid'||!duration.value)return;const button=e.currentTarget as HTMLElement;const track=button.parentElement!;button.setPointerCapture(e.pointerId);const update=(ev:PointerEvent)=>{const r=track.getBoundingClientRect();move(c,(ev.clientX-r.left)/r.width*duration.value)};const end=()=>{button.removeEventListener('pointermove',update);button.removeEventListener('pointerup',end);button.removeEventListener('pointercancel',end)};button.addEventListener('pointermove',update);button.addEventListener('pointerup',end);button.addEventListener('pointercancel',end)}
function saveTimeline(){void action(async()=>{const r=(await axios.put(base+'/videos/'+selected.value.kind+'/'+selected.value.id,{revision:revision.value,cues:cues.value},{headers:headers()})).data;revision.value=r.revision;source.value='individual';dirty.value=false;await load();await catalog();notice.value='Сохранено. Выбранные ролики активны и готовы к показу.'})}
function inherit(){if(!confirm('Удалить индивидуальные настройки и наследовать глобальное правило?'))return;void action(async()=>{await axios.delete(base+'/videos/'+selected.value.kind+'/'+selected.value.id,{headers:headers()});const r=(await axios.get(base+'/videos/'+selected.value.kind+'/'+selected.value.id,{headers:headers()})).data;cues.value=r.cues;revision.value=r.revision;source.value=r.source;dirty.value=false;await catalog()})}
async function playTestAd(){if(!testCue.value)return;const cue=testCue.value;testCue.value=null;main.value?.pause();const id=cue.creative_id||creatives.value.find(c=>c.status==='active')?.id;if(!id){error.value='Нет активного ролика для теста';testCue.value=null;return}try{testAd.value=nodeMediaUrl((await axios.get(base+'/creatives/'+id+'/preview',{headers:headers()})).data.media_url);testCue.value=null;testBlocked.value=false;await nextTick();await adVideo.value?.play()}catch{testBlocked.value=true}}
function testTransition(c:any){if(!main.value||!duration.value){error.value='Дождитесь загрузки видео';return}testAd.value='';testCue.value=c;testReturn.value=c.kind==='pre'?0:c.kind==='post'?duration.value:c.at_sec;main.value.currentTime=Math.max(0,testReturn.value-3);if(c.kind==='pre')void playTestAd();else void main.value.play().catch(()=>{error.value='Нажмите воспроизведение в плеере'})}
function timeUpdate(){position.value=main.value?.currentTime||0;if(testCue.value&&position.value>=testReturn.value-.05)void playTestAd()}
function endTest(){testAd.value='';if(main.value){main.value.currentTime=testReturn.value;if(testReturn.value<duration.value)void main.value.play().catch(()=>{})}}
onMounted(()=>void action(async()=>{await load();await catalog()}))
onBeforeUnmount(()=>{disposed=true;void stopPreview()})
</script>
<template>
<section class="studio">
<header><div class="eyebrow">AD STUDIO · MEDIA NODE</div><h1>Видео и реклама</h1><p>Ролики, автоматические правила и визуальные рекламные вставки.</p></header>
<nav aria-label="Режим Ad Studio"><button :class="{active:mode==='campaigns'}" @click="mode='campaigns'">Ролики и авто-правила</button><button :class="{active:mode==='timeline'}" @click="mode='timeline'">Визуальная студия таймингов</button></nav>
<p v-if="error" role="alert" class="error">{{error}}</p><p v-if="notice" role="status" class="notice">{{notice}}</p>
<div v-if="mode==='campaigns'">
<form class="panel upload" @submit.prevent="upload"><h2>Загрузить рекламный ролик</h2><div class="grid"><label>Название<input v-model="title" required maxlength="160"></label><label>Видео · MP4 / WebM · до 100 МиБ<input ref="fileInput" type="file" accept="video/mp4,video/webm" required @change="selectFile"></label><label>Ссылка рекламодателя<input v-model="cta" type="url" placeholder="https://…"></label><label>Пропуск<select v-model="skip"><option :value="null">Без пропуска</option><option :value="5">Через 5 сек</option><option :value="10">Через 10 сек</option></select></label></div><button class="primary" :disabled="busy||!file">{{busy?'Загрузка и обработка · '+progress+'%':'Загрузить и активировать'}}</button><p>Файл отправляется напрямую на Media Node. Статус после обработки — «Активен»; показ начнётся в сохранённых размещениях.</p></form>
<section class="panel"><h2>Автоматическое размещение</h2><label class="check"><input v-model="globalEnabled" type="checkbox" role="switch">Автоматически показывать рекламу во всех фильмах и сериалах</label><div class="row"><label class="check"><input v-model="globalPre" type="checkbox">Pre-roll · в начале · 00:00</label><label class="check"><input v-model="globalMid" type="checkbox">Mid-roll · каждые N минут</label><label class="check"><input v-model="globalPost" type="checkbox">Post-roll · в конце</label></div><div class="row"><label v-if="globalMid">Интервал, мин<input v-model.number="minutes" type="number" min="1" max="120"></label><label>Ролик<select v-model="globalCreative"><option value="">Ротация активных роликов</option><option v-for="c in creatives" :key="c.id" :value="c.id">{{c.title}}</option></select></label><button :disabled="busy" @click="saveGlobal">Сохранить авто-правило</button></div><p>Индивидуальные настройки важнее правил жанра; правила жанра важнее общего правила. PRO без рекламы сохраняется.</p><details v-if="rules.some(r=>r.scope!=='all'||r.genre_id!=null)"><summary>Сохранённые специальные правила</summary><p v-for="r in rules.filter(r=>r.scope!=='all'||r.genre_id!=null)" :key="r.id">{{r.scope}} · жанр {{r.genre_id??'все'}} · {{r.enabled?'Включено':'Выключено'}}. Индивидуальные точки настраиваются в студии.</p></details></section>
<div class="library"><article v-for="c in creatives" :key="c.id" class="panel creative"><div class="row spread"><h2>{{c.title}}</h2><button role="switch" :aria-checked="c.status==='active'" :class="{live:c.status==='active'}" :disabled="busy" @click="toggle(c)">{{c.status==='active'?'Вкл · Активен':'Выкл · На паузе'}}</button></div><p>{{Number(c.duration_sec).toFixed(1)}} сек · {{(c.byte_size/1048576).toFixed(1)}} МиБ · Media Node</p><div class="stats"><div>Показы<strong>{{c.impressions}}</strong></div><span>→</span><div>Досмотры<strong>{{rate(c.completions,c.impressions)}}</strong><small>{{c.completions}} завершений</small></div><span>→</span><div>CTR<strong>{{rate(c.clicks,c.impressions)}}</strong><small>{{c.clicks}} кликов</small></div></div><div class="row"><button :disabled="busy" @click="showPreview(c)">Предпросмотр</button><button @click="editing=editing===c.id?'':c.id">Настройки</button><button @click="creativeId=c.id;mode='timeline'">Разместить в видео</button></div><video v-if="previewId===c.id&&previewUrl" :src="previewUrl" controls playsinline preload="auto" class="preview" @error="error='Ссылка истекла или видео недоступно. Обновите предпросмотр.'"></video><form v-if="editing===c.id" class="grid" @submit.prevent="saveCreative(c)"><label>Название<input v-model="c.title" required maxlength="160"></label><label>Ссылка<input v-model="c.cta_url" type="url"></label><label>Текст кнопки<input v-model="c.cta_text" maxlength="80"></label><label>Пропуск<select v-model="c.skip_after"><option :value="null">Без пропуска</option><option :value="5">Через 5 сек</option><option :value="10">Через 10 сек</option></select></label><button :disabled="busy">Сохранить настройки</button></form></article></div><p v-if="!creatives.length" class="panel">Пока нет роликов. Загрузите первый файл.</p>
</div>
<div v-else>
<form class="row panel" @submit.prevent="search"><select v-model="kind" aria-label="Тип видео" @change="search"><option value="movie">Фильмы</option><option value="episode">Серии сериалов</option></select><input v-model="q" aria-label="Поиск фильма или серии" placeholder="Найти фильм или серию" maxlength="120"><button :disabled="busy">Найти</button><span>{{total}} видео</span></form>
<div class="editor"><aside class="panel catalog"><button v-for="v in videos" :key="v.id" :class="{active:selected?.id===v.id}" :disabled="busy" @click="openVideo(v)"><strong>{{v.title}}</strong><small>{{v.cue_count}} вставок · {{v.override?'индивидуально':'авто-правила'}}</small></button><p v-if="!videos.length">Нет доступных видео по этому запросу.</p><div class="row"><button :disabled="busy||offset===0" @click="page(-30)">Назад</button><button :disabled="busy||offset+30>=total" @click="page(30)">Далее</button></div></aside>
<div v-if="selected" class="panel timeline"><div class="row spread"><h2>{{selected.title}}</h2><span>{{dirty?'Есть несохранённые изменения':'Сохранено'}}</span></div><p>Поток: Media Node · {{format(duration)}}. Вставки: {{source==='individual'?'индивидуальные':source==='global'?'авто-правило':'ещё не добавлены'}}.</p><div class="player-wrap"><video ref="main" :src="mainUrl||undefined" class="preview" controls playsinline preload="auto" @loadedmetadata="duration=Number.isFinite(main?.duration)?main!.duration:duration" @timeupdate="timeUpdate" @ended="testCue&&playTestAd()" @error="error='Поток недоступен. Повторите выбор видео.'"></video><div v-if="testAd" class="test-overlay"><video ref="adVideo" :src="testAd" playsinline preload="auto" @ended="endTest" @error="error='Рекламный ролик недоступен';endTest()"></video><span>Тест рекламы · без записи статистики</span><button v-if="testBlocked" @click="adVideo?.play();testBlocked=false">Воспроизвести рекламу</button><button @click="endTest">Завершить тест</button></div></div><p v-if="busy&&!mainUrl" role="status">Подключение к Media Node…</p>
<label>Позиция · {{format(position)}}<input type="range" min="0" :max="duration||1" step="1" :value="position" :disabled="!mainUrl" @input="seek"></label><div class="markers" aria-label="Рекламные вставки"><button v-for="c in ordered" :key="c.id" :style="{left:Math.min(100,100*cueSecond(c)/(duration||1))+'%'}" :aria-label="cueLabel(c)+'; стрелки перемещают Mid-roll'" :title="cueLabel(c)" @pointerdown="drag(c,$event)" @keydown.left.prevent="move(c,c.at_sec-1)" @keydown.right.prevent="move(c,c.at_sec+1)" @click="main&&(main.currentTime=cueSecond(c))">◆</button></div>
<label>Ролик для новой вставки<select v-model="creativeId"><option value="">Ротация активных роликов</option><option v-for="c in creatives" :key="c.id" :value="c.id">{{c.title}}</option></select></label><div class="row quick"><button :disabled="busy||!duration" @click="add('pre')">+ В начало (Pre-roll)</button><button :disabled="busy||!duration" @click="add('mid',duration/2)">+ В середину (50%)</button><button :disabled="busy||!duration" @click="add('post')">+ В конец (Post-roll)</button><button class="primary" :disabled="busy||!duration" @click="add(position<1?'pre':'mid',position)">+ Вставить рекламу в эту секунду ({{format(position)}})</button></div>
<div v-for="c in ordered" :key="c.id" class="cue"><b>{{cueLabel(c)}}</b><input v-if="c.kind==='mid'" type="range" :value="c.at_sec" min="1" :max="Math.max(1,Math.round(duration)-1)" :aria-label="'Переместить '+cueLabel(c)" @input="move(c,Number(($event.target as HTMLInputElement).value))"><select v-model="c.creative_id" aria-label="Ролик для вставки" @change="dirty=true"><option :value="null">Ротация активных</option><option v-for="ad in creatives" :key="ad.id" :value="ad.id">{{ad.title}}</option></select><button :disabled="busy||!mainUrl" @click="testTransition(c)">▶ Тест перехода</button><button @click="cues=cues.filter(x=>x.id!==c.id);dirty=true">Удалить</button></div><p v-if="!cues.length">Нет вставок. Пустой индивидуальный список отключает рекламу для этого видео.</p><div class="row"><button class="primary" :disabled="busy" @click="saveTimeline">Сохранить</button><button :disabled="busy" @click="inherit">Наследовать глобальное правило</button></div></div><div v-else class="panel empty">Выберите фильм или серию слева. Откроются реальный поток и визуальный таймлайн.</div></div>
</div>
</section>
</template>
<style scoped>
